package com.bank.wfee.service;

import java.util.logging.Logger;

// Finds the cheapest total fee to climb past the last stage (1 or 2 steps).
public class WorkflowFeeService {
    private static final Logger log = Logger.getLogger(WorkflowFeeService.class.getName());

    public long minCost(int[] fees) {
        long down1 = 0, down2 = 0;                  // cheapest cost to last two steps
        for (int fee : fees) {
            long cur = fee + Math.min(down1, down2);  // own fee + cheaper predecessor
            down2 = down1;
            down1 = cur;                            // slide the window
        }
        long result = Math.min(down1, down2);       // top from last or second-last
        final long r = result;
        log.info(() -> "Cheapest total fee to top = " + r);
        return result;
    }
}
