package com.bank.wfee;

import com.bank.wfee.service.WorkflowFeeService;
import java.util.logging.Logger;

public class WorkflowFeeApplication {
    private static final Logger log = Logger.getLogger(WorkflowFeeApplication.class.getName());

    public static void main(String[] args) {
        WorkflowFeeService service = new WorkflowFeeService();
        int[] fees = {10, 15, 20};      // processing fee at each stage
        long best = service.minCost(fees);
        log.info("Minimum total processing fee to completion: " + best);
    }
}
